import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse(`{"title":"Update Catalog Rule","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"update","title":"Update Catalog Rule","description":"Update a catalog rule's name and discount. Update is a partial merge — send only the fields you change.","query":"curl -X PUT \\"https://your-domain.com/api/admin/marketing/catalog-rules/126\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d '{\\n    \\"name\\": \\"Summer Collection 15% Off\\",\\n    \\"discount_amount\\": 15\\n  }'\\n","variables":"{}\\n","response":"{\\n  \\"id\\": 126,\\n  \\"name\\": \\"Summer Collection 15% Off\\",\\n  \\"description\\": \\"Sitewide 10% off the summer collection\\",\\n  \\"startsFrom\\": null,\\n  \\"endsTill\\": null,\\n  \\"status\\": 1,\\n  \\"sortOrder\\": 0,\\n  \\"conditionType\\": 1,\\n  \\"conditions\\": [],\\n  \\"endOtherRules\\": 0,\\n  \\"actionType\\": \\"by_percent\\",\\n  \\"discountAmount\\": 15,\\n  \\"channels\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"default\\",\\n      \\"name\\": \\"Default\\"\\n    }\\n  ],\\n  \\"customerGroups\\": [\\n    {\\n      \\"id\\": 2,\\n      \\"code\\": \\"general\\",\\n      \\"name\\": \\"General\\"\\n    }\\n  ],\\n  \\"createdAt\\": \\"2026-06-17T12:13:15+05:30\\",\\n  \\"updatedAt\\": \\"2026-06-17T12:20:42+05:30\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/marketing/promotions/catalog-rules-update.md","filePath":"api/rest-api/admin/marketing/promotions/catalog-rules-update.md","lastUpdated":1787725411000}`),n={name:"api/rest-api/admin/marketing/promotions/catalog-rules-update.md"};function r(i,t,s,c,l,u){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="update-catalog-rule" tabindex="-1">Update Catalog Rule <a class="header-anchor" href="#update-catalog-rule" aria-label="Permalink to &quot;Update Catalog Rule&quot;">​</a></h1><p>Updates an existing catalog rule — the <strong>Edit Rule</strong> action on the admin <strong>Marketing → Promotions → Catalog Rules</strong> screen. Saving recomputes affected product prices in the background.</p><p>New here? Read the <a href="/api/rest-api/admin/marketing/promotions/catalog-rules/">Catalog Rules overview</a> for what a catalog rule does and how its fields behave.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/marketing/catalog-rules/{id}</code></td><td>PUT</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.promotions.catalog_rules.edit</code> permission.</li><li>The update is a <strong>partial merge</strong> — send only the fields you want to change; omitted fields keep their existing values.</li><li>When <code>channels</code> or <code>customer_groups</code> is supplied, that list <strong>replaces</strong> the rule&#39;s current channels / customer groups. Omit them to leave the existing sets untouched. They are sent as plain id arrays.</li><li>Returns the full updated rule payload. In the response, <code>channels</code> and <code>customerGroups</code> are <strong>arrays of objects</strong> (each <code>{ id, code, name }</code>).</li></ul><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>no</td><td>Rule name</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Free-text description</td></tr><tr><td><code>starts_from</code></td><td>string</td><td>no</td><td>Start date (<code>YYYY-MM-DD</code>) or <code>null</code></td></tr><tr><td><code>ends_till</code></td><td>string</td><td>no</td><td>End date (<code>YYYY-MM-DD</code>) or <code>null</code>; must be <code>&gt;= starts_from</code></td></tr><tr><td><code>status</code></td><td>int</td><td>no</td><td><code>0</code> inactive / <code>1</code> active</td></tr><tr><td><code>sort_order</code></td><td>int</td><td>no</td><td>Priority — lower runs first</td></tr><tr><td><code>condition_type</code></td><td>int</td><td>no</td><td><code>1</code> match all conditions / <code>0</code> match any</td></tr><tr><td><code>conditions</code></td><td>array</td><td>no</td><td>Product-attribute filters</td></tr><tr><td><code>end_other_rules</code></td><td>int</td><td>no</td><td><code>1</code> stops lower-priority rules from also applying</td></tr><tr><td><code>action_type</code></td><td>string</td><td>no</td><td><code>by_percent</code>, <code>by_fixed</code>, <code>to_percent</code>, <code>to_fixed</code></td></tr><tr><td><code>discount_amount</code></td><td>number</td><td>no</td><td>Discount value; capped at <code>100</code> when <code>action_type</code> is <code>by_percent</code></td></tr><tr><td><code>channels</code></td><td>int[]</td><td>no</td><td>Replaces the rule&#39;s channels when supplied</td></tr><tr><td><code>customer_groups</code></td><td>int[]</td><td>no</td><td>Replaces the rule&#39;s customer groups when supplied</td></tr></tbody></table>',9)]))}const m=e(n,[["render",r]]);export{h as __pageData,m as default};
